import UIKit

class PushNavigator {
    @MainActor
    static func pushDetail(onto nav: UINavigationController, title: String) {
        let detail = UIViewController()
        detail.navigationItem.title = title
        nav.pushViewController(detail, animated: false)
    }
}

let navInst = UINavigationController(rootViewController: UIViewController())
PushNavigator.pushDetail(onto: navInst, title: "Profile")
print("Top title: \(navInst.topViewController?.navigationItem.title ?? "none")")

import UIKit

class ModalPresenter {
    @MainActor
    static func presentSheet(from parent: UIViewController, modal: UIViewController) {
        modal.modalPresentationStyle = .pageSheet
        parent.present(modal, animated: false)
    }
}

let pVC = UIViewController()
let mVC = UIViewController()
ModalPresenter.presentSheet(from: pVC, modal: mVC)
print("Presented style: \(mVC.modalPresentationStyle == .pageSheet)")

import UIKit

@MainActor
protocol DismissNotifier: AnyObject {
    func didDismiss()
}

class NotifierManager: DismissNotifier {
    var dismissed = false
    func didDismiss() {
        dismissed = true
    }
}

class ModalController: UIViewController {
    weak var delegate: DismissNotifier?
    func close() {
        delegate?.didDismiss()
    }
}

let mgr = NotifierManager()
let mController = ModalController()
mController.delegate = mgr
mController.close()
print("Dismissed: \(mgr.dismissed)")
